namespace sv_470ff8e5346f4778a0292a712f6edb56.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped (per-circuit) service that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.Find(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;
        OnChange?.Invoke();
    }
}

namespace sv_470ff8e5346f4778a0292a712f6edb56.Services;

/// <summary>
/// Scoped (per-circuit) service that polls for low-stock alerts and
/// broadcasts the latest count to all subscribed components.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired on the thread-pool when new alert data arrives.
    /// Subscribers must marshal to the UI thread via InvokeAsync.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>Call when a polling subscriber is disposed / leaves the page.</summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);
        CurrentAlertCount = count;

        if (OnAlertCountChanged is { } handler)
        {
            await handler.Invoke();
        }
    }

    public void Dispose()
    {
        _timer?.Dispose();
        _timer = null;
    }
}

