namespace sv_470ff8e5346f4778a0292a712f6edb56.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped (per-circuit) service that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo CurrentWarehouse { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.Find(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == CurrentWarehouse.Id)
            return;

        CurrentWarehouse = warehouse;
        OnChange?.Invoke();
    }
}

